@startuml
abstract class Well {
  + code : string
}

class OnshoreWell {
  + surfaceExtension : float
}

class OffshoreWell {
  + installationYear : int
}

class OilCompany {
  + taxCode : string
  + numberOfEmployees : int
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

class Extraction {
  + quantity : float
}

OnshoreWell --|> Well
OffshoreWell --|> Well

Well "*" -- "*" OilCompany : extracts
Extraction "*" -- "1" Well
Extraction "*" -- "1" OilCompany

OffshoreWell "0..1" o-- "0..1" GeographicalArea

@enduml

